function parseArguments(argv) {
  const result = {
    databasePath: "",
    mode: "",
    json: false,
    backupDir: "",
  };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--db") {
      result.databasePath = argv[index + 1] || "";
      index += 1;
    } else if (argument === "--dry-run") {
      result.mode = result.mode ? "invalid" : "dry-run";
