      result.mode = result.mode ? "invalid" : "apply";
    } else if (argument === "--json") {
      result.json = true;
    } else if (argument === "--backup-dir") {
      result.backupDir = argv[index + 1] || "";
      index += 1;
    } else {
      throw new SchemaMigratorError(
        "INVALID_ARGUMENT",
        `Argumento desconhecido: ${argument}`
      );
    }
  }
  if (!result.databasePath) {
    throw new SchemaMigratorError(
      "DATABASE_PATH_REQUIRED",
      "Informe um caminho explícito com --db."
    );
  }
  if (!["dry-run", "apply"].includes(result.mode)) {
    throw new SchemaMigratorError(
      "MODE_REQUIRED",
      "Informe exatamente um modo: --dry-run ou --apply."
    );
  }
  if (result.backupDir && !path.isAbsolute(result.backupDir)) {
    throw new SchemaMigratorError(
      "BACKUP_DIRECTORY_MUST_BE_ABSOLUTE",
      "O diretório de backup deve usar caminho absoluto."
    );
  }
  return result;
}

function fileHash(filePath) {
  return crypto
    .createHash("sha256")
    .update(fs.readFileSync(filePath))
    .digest("hex");
}

function sanitizeMigrationId(migrationId) {
  const sanitized = String(migrationId)
    .normalize("NFKD")
    .replace(/[^A-Za-z0-9._-]+/g, "_")
    .replace(/^[-_.]+|[-_.]+$/g, "");
  if (!sanitized) {
    throw new SchemaMigratorError(
      "INVALID_MIGRATION_ID_FOR_BACKUP",
      "ID da migração não pode ser usado com segurança no nome do backup."
    );
  }
  return sanitized;
}

function backupPathFor(databasePath, migrationId, backupDir = "") {
  const parsed = path.parse(databasePath);
  const suffix = sanitizeMigrationId(migrationId);
  const destinationDir = backupDir || parsed.dir;
  const basePath = path.join(
    destinationDir,
    `${parsed.name}.before-schema-${suffix}${parsed.ext || ".db"}`
  );
  if (!fs.existsSync(basePath)) return basePath;
  let sequence = 2;
  while (true) {
    const candidate = path.join(
      destinationDir,
      `${parsed.name}.before-schema-${suffix}-${sequence}${parsed.ext || ".db"}`
    );
    if (!fs.existsSync(candidate)) return candidate;
    sequence += 1;
  }
}

function createVerifiedBackup(databasePath, migrationId, backupDir = "") {
  const walPath = `${databasePath}-wal`;
  const shmPath = `${databasePath}-shm`;
  if (fs.existsSync(walPath) || fs.existsSync(shmPath)) {
    throw new SchemaMigratorError(
      "WAL_OR_SHM_PRESENT",
      "Backup pré-migração recusado: existem arquivos WAL ou SHM."
    );
  }

  const lockDb = new DatabaseSync(databasePath);
  let locked = false;
  try {
    lockDb.exec("PRAGMA busy_timeout = 5000");
    lockDb.exec("BEGIN EXCLUSIVE");
    locked = true;
    const beforeHash = fileHash(databasePath);
    const destinationDir = backupDir || path.dirname(databasePath);
    fs.mkdirSync(destinationDir, { recursive: true });
    const backupPath = backupPathFor(databasePath, migrationId, destinationDir);
    if (path.resolve(backupPath) === path.resolve(databasePath)) {
      throw new SchemaMigratorError(
        "BACKUP_DESTINATION_INVALID",
        "O backup não pode substituir o próprio banco."
      );
    }
    fs.copyFileSync(databasePath, backupPath, fs.constants.COPYFILE_EXCL);
    const backupHash = fileHash(backupPath);
    if (beforeHash !== backupHash) {
      throw new SchemaMigratorError(
        "BACKUP_HASH_MISMATCH",
        "Hash do backup pré-migração diverge do banco de teste."
      );
    }
    lockDb.exec("ROLLBACK");
    locked = false;
    return { backupPath, beforeHash, backupHash };
  } finally {
    if (locked) {
      try {
        lockDb.exec("ROLLBACK");
      } catch {
        // O fechamento da conexão libera o lock em último caso.
      }
    }
    lockDb.close();
  }
}

let jsonMode = process.argv.includes("--json");
let jsonContext = {
  mode: process.argv.includes("--dry-run") ? "dry-run" : "apply",
  database: null,
  pending: [],
  applied: [],
  backupPath: null,
  schemaVersion: null,
  migrationId: null,
};

function logTechnical(entry) {
  const fields = Object.entries(entry)
    .map(([key, value]) => `${key}=${JSON.stringify(value)}`)
    .join(" ");
  const output = `[schema-migrator] ${fields}`;
  if (jsonMode) console.error(output);
  else console.log(output);
}

function printReport(report, backup = null) {
  console.log(`modo=${report.mode}`);
  console.log(`banco=${report.databasePath}`);
  console.log(`appVersion=${report.appVersion}`);
  console.log(`integrity_check=${report.healthAfter?.integrityCheck || report.health.integrityCheck}`);
  console.log(
    `foreign_key_violations=${
      report.healthAfter?.foreignKeyViolations ?? report.health.foreignKeyViolations
    }`
  );
  console.log(`aplicadas_agora=${(report.appliedNow || []).join(",") || "nenhuma"}`);
  console.log(`pendentes=${report.pending.map((item) => item.id || item).join(",") || "nenhuma"}`);
  if (backup) {
    console.log(`backup=${backup.backupPath}`);
    console.log(`backup_hash_ok=${backup.beforeHash === backup.backupHash}`);
  }
}

function sanitizeErrorMessage(message) {
  let sanitized = String(message);
  const databaseArgument = process.argv[process.argv.indexOf("--db") + 1] || "";
  if (databaseArgument) {
    sanitized = sanitized.replaceAll(String(databaseArgument), "[banco]");
  }
  if (jsonContext.backupPath) {
    sanitized = sanitized.replaceAll(String(jsonContext.backupPath), "[backup]");
  }
  return sanitized;
}

function main() {
  const options = parseArguments(process.argv.slice(2));
  jsonMode = options.json;
  jsonContext.mode = options.mode;
  jsonContext.database = path.basename(options.databasePath);
  const databasePath = path.resolve(options.databasePath);
  if (!fs.existsSync(databasePath)) {
    throw new SchemaMigratorError(
      "DATABASE_NOT_FOUND",
      `Banco não encontrado: ${databasePath}`
    );
  }

  if (options.mode === "dry-run") {
    const report = inspectDatabase(databasePath, { logger: logTechnical });
    if (options.json) {
      const applied = report.applied.map((item) => item.id);
      console.log(JSON.stringify({
        ok: true,
        mode: "dry-run",
        database: path.basename(databasePath),
        pending: report.pending.map((item) => item.id),
        applied,
        backupPath: null,
        schemaVersion: applied.at(-1) || null,
        migrationId: null,
        integrityCheck: report.health.integrityCheck,
        foreignKeyViolations: report.health.foreignKeyViolations,
        code: "OK",
      }));
    } else {
      printReport(report);
    }
    return;
  }

  const inspection = inspectDatabase(databasePath, { logger: logTechnical });
  jsonContext.pending = inspection.pending.map((item) => item.id);
  jsonContext.applied = inspection.applied.map((item) => item.id);
  if (inspection.pending.length === 0) {
    const report = {
      ...inspection,
      mode: "apply",
      appliedNow: [],
    };
    if (options.json) {
      console.log(JSON.stringify({
        ok: true,
        mode: "apply",
        database: path.basename(databasePath),
        pending: [],
        applied: [],
        backupPath: null,
        schemaVersion: jsonContext.applied.at(-1) || null,
        migrationId: null,
        integrityCheck: report.health.integrityCheck,
        foreignKeyViolations: report.health.foreignKeyViolations,
        code: "OK",
      }));
    } else {
      printReport(report);
    }
    return;
  }

  const lastPendingMigration = inspection.pending.at(-1);
  jsonContext.migrationId = lastPendingMigration.id;
  const backup = createVerifiedBackup(
    databasePath,
    lastPendingMigration.id,
    options.backupDir
  );
  jsonContext.backupPath = backup.backupPath;
  const report = applyMigrations(databasePath, { logger: logTechnical });
  if (options.json) {
    console.log(JSON.stringify({
      ok: true,
      mode: "apply",
      database: path.basename(databasePath),
      pending: report.pending,
      applied: report.appliedNow,
      backupPath: backup.backupPath,
      schemaVersion: report.applied.at(-1) || null,
      migrationId: report.appliedNow.at(-1) || lastPendingMigration.id,
      integrityCheck: report.healthAfter.integrityCheck,
      foreignKeyViolations: report.healthAfter.foreignKeyViolations,
      code: "OK",
    }));
  } else {
    printReport(report, backup);
  }
}

try {
  main();
} catch (error) {
  const code =
    error instanceof SchemaMigratorError ? error.code : "UNEXPECTED_ERROR";
  const message =
    error instanceof Error ? error.message : "Falha desconhecida no migrador.";
  const migrationId =
    error instanceof SchemaMigratorError ? error.details?.migrationId || null : null;
  if (jsonMode) {
    console.log(JSON.stringify({
      ok: false,
      ...jsonContext,
      migrationId: migrationId || jsonContext.migrationId,
      code,
      message: sanitizeErrorMessage(message),
    }));
  } else {
    console.error(`[schema-migrator] erro=${code} mensagem=${JSON.stringify(message)}`);
  }
  process.exitCode = 1;
}

import { promises as fs } from "fs";
import path from "path";
import { NextResponse } from "next/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type Contexto = {
  params: Promise<{ path?: string[] }> | { path?: string[] };
};

function raizDadosRuntime() {
  const direto = process.env.NIO_OS_DATA_DIR || process.env.NIO_OS_APPDATA_DIR;

  if (direto) return direto;

  if (process.platform === "win32") {
    return path.join(process.env.APPDATA || process.cwd(), "Nio-OS");
  }

  return path.join(process.env.HOME || process.cwd(), ".nio-os");
}

function mimeType(arquivo: string) {
  const ext = path.extname(arquivo).toLowerCase();

  if (ext === ".png") return "image/png";
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".webp") return "image/webp";
  if (ext === ".gif") return "image/gif";
  if (ext === ".svg") return "image/svg+xml";
  if (ext === ".pdf") return "application/pdf";

  return "application/octet-stream";
}

function partesSeguras(partes: string[]) {
  return partes
    .map((parte) => decodeURIComponent(String(parte || "")).trim())
    .filter(Boolean)
    .map((parte) => path.basename(parte))
    .filter((parte) => parte && parte !== "." && parte !== "..");
}

function caminhoUploadRuntime(partes: string[]) {
  const base = path.join(raizDadosRuntime(), "public", "uploads");
  const seguras = partesSeguras(partes);
  const arquivo = path.resolve(base, ...seguras);
  const baseResolvida = path.resolve(base);

  if (arquivo !== baseResolvida && !arquivo.startsWith(baseResolvida + path.sep)) {
    throw new Error("Caminho de upload inválido.");
  }

  return arquivo;
}

export async function GET(_request: Request, contexto: Contexto) {
  try {
    const params = await contexto.params;
    const partes = Array.isArray(params?.path) ? params.path : [];

    if (partes.length === 0) {
      return NextResponse.json({ message: "Arquivo não informado." }, { status: 400 });
    }

    const arquivo = caminhoUploadRuntime(partes);
    const stat = await fs.stat(arquivo);

    if (!stat.isFile()) {
      return NextResponse.json({ message: "Arquivo não encontrado." }, { status: 404 });
    }

    const buffer = await fs.readFile(arquivo);

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        "Content-Type": mimeType(arquivo),
        "Content-Length": String(buffer.length),
        "Cache-Control": "no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0",
        Pragma: "no-cache",
        Expires: "0",
      },
    });
  } catch (error) {
    console.error("Erro ao carregar upload runtime:", error);

    return NextResponse.json(
      { message: "Arquivo não encontrado." },
      {
        status: 404,
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  }
}

import { randomUUID } from "crypto";
import { mkdir, writeFile } from "fs/promises";
import path from "path";
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { resolverOperadorPadrao } from "@/lib/operadorSistema";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = {
  name?: string | null;
  username?: string | null;
  email?: string | null;
};

const TAMANHO_MAXIMO_ANEXO = 10 * 1024 * 1024;

const TIPOS_PERMITIDOS = new Map([
  [".png", "image/png"],
  [".jpg", "image/jpeg"],
  [".jpeg", "image/jpeg"],
  [".webp", "image/webp"],
  [".pdf", "application/pdf"],
]);

function nomeOperador(usuario: unknown) {
  const dadosUsuario = usuario as UsuarioSessao | null;

  return (
    dadosUsuario?.name || dadosUsuario?.username || dadosUsuario?.email || "Sistema"
  );
}

function limparNomeArquivo(nome: string) {
  return nome
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "")
    .toLowerCase();
}

function normalizarExtensao(nomeArquivo: string) {
  return path.extname(nomeArquivo || "").toLowerCase();
}

function urlProtegidaAnexo(fileName: string) {
  return `/api/uploads/anexos/${encodeURIComponent(fileName)}`;
}

function caminhoDiretorioAnexos() {
  return path.join(process.cwd(), "storage", "uploads", "anexos");
}

function parecePng(buffer: Buffer) {
  const assinatura = Buffer.from([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
  ]);

  return buffer.length >= assinatura.length && buffer.subarray(0, 8).equals(assinatura);
}

function pareceJpeg(buffer: Buffer) {
  return buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
}

function pareceWebp(buffer: Buffer) {
  return (
    buffer.length >= 12 &&
    buffer.subarray(0, 4).toString("ascii") === "RIFF" &&
    buffer.subarray(8, 12).toString("ascii") === "WEBP"
  );
}

function parecePdf(buffer: Buffer) {
  return buffer.length >= 4 && buffer.subarray(0, 4).toString("ascii") === "%PDF";
}

function arquivoPareceValido(buffer: Buffer, extensao: string) {
  if (extensao === ".png") return parecePng(buffer);
  if (extensao === ".jpg" || extensao === ".jpeg") return pareceJpeg(buffer);
  if (extensao === ".webp") return pareceWebp(buffer);
  if (extensao === ".pdf") return parecePdf(buffer);

  return false;
}

function sanitizarAnexo<T extends { fileName: string; url: string | null }>(anexo: T) {
  return {
    ...anexo,
    url: urlProtegidaAnexo(anexo.fileName),
  };
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    if (!id) {
      return NextResponse.json(
        { message: "ID da OS não informado." },
        { status: 400 }
      );
    }

    const ordemExiste = await prisma.serviceOrder.findUnique({
      where: {
        id,
      },
      select: {
        id: true,
      },
    });

    if (!ordemExiste) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const anexos = await prisma.serviceOrderAttachment.findMany({
      where: {
        serviceOrderId: id,
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    return NextResponse.json(anexos.map(sanitizarAnexo));
  } catch (error) {
    console.error("Erro ao buscar anexos da OS:", error);

    return NextResponse.json(
      { message: "Erro ao buscar anexos da OS." },
      { status: 500 }
    );
  }
}

export async function POST(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    if (!id) {
      return NextResponse.json(
        { message: "ID da OS não informado." },
        { status: 400 }
      );
    }

    const ordem = await prisma.serviceOrder.findUnique({
      where: { id },
      select: {
        id: true,
        osNumber: true,
      },
    });

    if (!ordem) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const formData = await request.formData().catch(() => null);

    if (!formData) {
      return NextResponse.json(
        { message: "Dados inválidos para envio do anexo." },
        { status: 400 }
      );
    }

    const arquivo =
      formData.get("file") ||
      formData.get("arquivo") ||
      formData.get("anexo") ||
      formData.get("attachment");

    if (!(arquivo instanceof File)) {
      return NextResponse.json(
        { message: "Nenhum arquivo enviado." },
        { status: 400 }
      );
    }

    if (arquivo.size <= 0) {
      return NextResponse.json(
        { message: "O arquivo enviado está vazio." },
        { status: 400 }
      );
    }

    if (arquivo.size > TAMANHO_MAXIMO_ANEXO) {
      return NextResponse.json(
        { message: "O anexo deve ter no máximo 10MB." },
        { status: 400 }
      );
    }

    const originalName = arquivo.name || "arquivo";
    const extensao = normalizarExtensao(originalName);
    const mimePermitido = TIPOS_PERMITIDOS.get(extensao);

    if (!mimePermitido) {
      return NextResponse.json(
        {
          message:
            "Tipo de anexo não permitido. Envie PNG, JPG, WEBP ou PDF.",
        },
        { status: 400 }
      );
    }

    const bytes = await arquivo.arrayBuffer();
    const buffer = Buffer.from(bytes);

    if (!arquivoPareceValido(buffer, extensao)) {
      return NextResponse.json(
        {
          message:
            "O arquivo enviado não parece corresponder ao tipo informado.",
        },
        { status: 400 }
      );
    }

    const uploadDir = caminhoDiretorioAnexos();
    await mkdir(uploadDir, { recursive: true });

    const baseName = limparNomeArquivo(
      path.basename(originalName, extensao) || "anexo"
    );

    const numeroOS = String(ordem.osNumber || "sem-numero").replace(/\D/g, "") || "sem-numero";
    const fileName = `os-${numeroOS}-${Date.now()}-${randomUUID()}-${baseName}${extensao}`;
    const filePath = path.join(uploadDir, fileName);

    await writeFile(filePath, buffer, {
      flag: "wx",
    });

    const url = urlProtegidaAnexo(fileName);
    const userName = await resolverOperadorPadrao(nomeOperador(acesso.usuario));

    const anexo = await prisma.serviceOrderAttachment.create({
      data: {
        serviceOrderId: id,
        fileName,
        originalName,
        url,
        mimeType: mimePermitido,
        size: arquivo.size,
      },
    });

    await prisma.orderHistory.create({
      data: {
        serviceOrderId: id,
        userName,
        action: "ANEXO_ADICIONADO",
        description: `Anexo adicionado à OS: ${originalName}.`,
      },
    });

    return NextResponse.json(sanitizarAnexo(anexo), { status: 201 });
  } catch (error) {
    console.error("Erro ao salvar anexo da OS:", error);

    return NextResponse.json(
      { message: "Erro ao salvar anexo da OS." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import fs from "fs/promises";
import path from "path";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
    anexoId: string;
  }>;
};

function nomeOperador(usuario: {
  name?: string | null;
  username?: string | null;
  email?: string | null;
} | null | undefined) {
  return (
    String(usuario?.name || usuario?.username || usuario?.email || "").trim() ||
    "Sistema"
  );
}

function caminhosPossiveisDoAnexo(url: string | null | undefined) {
  const valor = String(url || "").split("?")[0].trim();
  const nomeArquivo = path.basename(valor);

  if (!nomeArquivo || nomeArquivo === "." || nomeArquivo === "..") {
    return [];
  }

  const caminhos = [
    path.join(process.cwd(), "storage", "uploads", "anexos", nomeArquivo),
    path.join(process.cwd(), "public", "uploads", "anexos", nomeArquivo),
  ];

  if (valor.startsWith("/uploads/") || valor.startsWith("uploads/")) {
    caminhos.push(path.join(process.cwd(), "public", valor.replace(/^\/+/, "")));
  }

  return Array.from(new Set(caminhos));
}

async function removerArquivoFisico(url: string | null | undefined) {
  const caminhos = caminhosPossiveisDoAnexo(url);

  for (const caminho of caminhos) {
    try {
      await fs.unlink(caminho);
      return;
    } catch {
      // Se o arquivo físico não existir neste caminho, tenta o próximo.
    }
  }
}


export async function DELETE(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const userName = nomeOperador(acesso.usuario);

    const { id, anexoId } = await context.params;

    const anexo = await prisma.serviceOrderAttachment.findFirst({
      where: {
        id: anexoId,
        serviceOrderId: id,
      },
    });

    if (!anexo) {
      return NextResponse.json(
        { message: "Anexo não encontrado." },
        { status: 404 }
      );
    }

    await removerArquivoFisico(anexo.url);

    await prisma.serviceOrderAttachment.delete({
      where: {
        id: anexo.id,
      },
    });

    await prisma.serviceOrder.update({
      where: { id },
      data: {
        histories: {
          create: {
            userName,
            action: "ANEXO_REMOVIDO",
            description: `Anexo removido: ${anexo.originalName}`,
          },
        },
      },
    });

    return NextResponse.json({
      message: "Anexo removido com sucesso.",
    });
  } catch (error) {
    console.error("Erro ao remover anexo da OS:", error);

    return NextResponse.json(
      { message: "Erro ao remover anexo da OS." },
      { status: 500 }
    );
  }
}

import { readFile, stat } from "fs/promises";
import path from "path";
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    arquivo: string;
  }>;
};

function contentTypePorExtensao(nomeArquivo: string) {
  const ext = path.extname(nomeArquivo).toLowerCase();

  if (ext === ".png") return "image/png";
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".webp") return "image/webp";
  if (ext === ".pdf") return "application/pdf";

  return "application/octet-stream";
}

function nomeDownloadSeguro(nome: string) {
  return nome
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]/g, "-")
    .replace(/-+/g, "-")
    .slice(0, 120) || "anexo";
}

async function arquivoExiste(caminho: string) {
  try {
    const info = await stat(caminho);
    return info.isFile();
  } catch {
    return false;
  }
}

async function resolverCaminhoArquivo(nomeSeguro: string) {
  const caminhoProtegido = path.join(
    process.cwd(),
    "storage",
    "uploads",
    "anexos",
    nomeSeguro
  );

  if (await arquivoExiste(caminhoProtegido)) {
    return caminhoProtegido;
  }

  // Compatibilidade com anexos antigos que foram salvos em public/uploads/anexos.
  const caminhoAntigo = path.join(
    process.cwd(),
    "public",
    "uploads",
    "anexos",
    nomeSeguro
  );

  if (await arquivoExiste(caminhoAntigo)) {
    return caminhoAntigo;
  }

  return null;
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { arquivo } = await context.params;
    const nomeSeguro = path.basename(decodeURIComponent(arquivo || ""));

    if (!nomeSeguro || nomeSeguro !== decodeURIComponent(arquivo || "")) {
      return NextResponse.json(
        { message: "Anexo não informado." },
        { status: 400 }
      );
    }

    const anexo = await prisma.serviceOrderAttachment.findFirst({
      where: {
        fileName: nomeSeguro,
      },
      select: {
        fileName: true,
        originalName: true,
        mimeType: true,
      },
    });

    if (!anexo) {
      return NextResponse.json(
        { message: "Anexo não encontrado." },
        { status: 404 }
      );
    }

    const filePath = await resolverCaminhoArquivo(nomeSeguro);

    if (!filePath) {
      return NextResponse.json(
        { message: "Arquivo do anexo não encontrado." },
        { status: 404 }
      );
    }

    const buffer = await readFile(filePath);
    const contentType = anexo.mimeType || contentTypePorExtensao(nomeSeguro);
    const downloadName = nomeDownloadSeguro(anexo.originalName || nomeSeguro);

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        "Content-Type": contentType,
        "Content-Disposition": `inline; filename="${downloadName}"`,
        "Cache-Control": "no-store, no-cache, must-revalidate",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch (error) {
    console.error("Erro ao carregar anexo da OS:", error);

    return NextResponse.json(
      { message: "Erro ao carregar anexo da OS." },
      { status: 500 }
    );
  }
}

import { caminhoPublicoRuntime, caminhoUploadPublico } from "@/lib/runtimeStorage";
import { NextResponse } from "next/server";
import { mkdir, writeFile } from "fs/promises";
import path from "path";
import { randomUUID } from "crypto";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const TIPOS_PERMITIDOS = ["image/png", "image/jpeg", "image/webp"];
const EXTENSOES: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
};

function imagemValida(buffer: Buffer, type: string) {
  if (type === "image/png") {
    const assinatura = Buffer.from([
      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    ]);

    return buffer.length >= 8 && buffer.subarray(0, 8).equals(assinatura);
  }

  if (type === "image/jpeg") {
    return buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8;
  }

  if (type === "image/webp") {
    return (
      buffer.length >= 12 &&
      buffer.subarray(0, 4).toString("ascii") === "RIFF" &&
      buffer.subarray(8, 12).toString("ascii") === "WEBP"
    );
  }

  return false;
}

export async function POST(request: Request) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi([
      "produtos.criar",
      "produtos.editar",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const formData = await request.formData().catch(() => null);
    const file = formData?.get("imagem");

    if (!(file instanceof File)) {
      return NextResponse.json(
        { message: "Nenhuma imagem enviada." },
        { status: 400 }
      );
    }

    if (!TIPOS_PERMITIDOS.includes(file.type)) {
      return NextResponse.json(
        { message: "Envie uma imagem PNG, JPG ou WEBP." },
        { status: 400 }
      );
    }

    const maxSize = 3 * 1024 * 1024;

    if (file.size > maxSize) {
      return NextResponse.json(
        { message: "A imagem deve ter no máximo 3MB." },
        { status: 400 }
      );
    }

    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    if (!imagemValida(buffer, file.type)) {
      return NextResponse.json(
        { message: "O arquivo enviado não parece ser uma imagem válida." },
        { status: 400 }
      );
    }

    const extensao = EXTENSOES[file.type] || "png";
    const nomeArquivo = `produto-${Date.now()}-${randomUUID()}.${extensao}`;

    const uploadDir = caminhoUploadPublico("produtos");
    const filePath = path.join(uploadDir, nomeArquivo);

    await mkdir(uploadDir, { recursive: true });
    await writeFile(filePath, buffer);

    return NextResponse.json({
      message: "Imagem enviada com sucesso.",
      imageUrl: `/api/uploads/produtos/${nomeArquivo}`,
    });
  } catch (error) {
    console.error("Erro ao enviar imagem do produto:", error);

    return NextResponse.json(
      { message: "Erro ao enviar imagem do produto." },
      { status: 500 }
    );
  }
}

