  y: number,
  largura: number,
  altura: number
) {
  doc.font("Helvetica-Bold").fontSize(7).text(titulo, x, y);
  doc.roundedRect(x, y + 10, largura, altura, 4).stroke("#cbd5e1");
  doc.font("Helvetica").fontSize(8).text(valor || "-", x + 6, y + 16, {
    width: largura - 12,
    height: altura - 10,
    ellipsis: true,
  });
}

